def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water = int(my_status['no_water_days'])

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    dangerous_prev = []
    desperate_count = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                desperate_count += 1
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                b = float(bid)
                prev_bids.append(b)
                if b >= 90:
                    dangerous_prev.append(b)

    if not alive:
        return min(budget, 18.0)

    low_supply = supply <= 17
    mid_supply = supply <= 20
    urgent = hp <= 3 or no_water >= 1
    critical = hp <= 2 or no_water >= 2

    highest_prev = max(prev_bids) if prev_bids else 0.0
    moderate_prev = 0.0
    if prev_bids:
        filtered = [b for b in prev_bids if b < 90]
        if filtered:
            moderate_prev = max(filtered)

    target = 0.0

    if critical:
        if dangerous_prev:
            target = min(0.92 * DAILY_SALARY, max(dangerous_prev) + 2.0)
        elif highest_prev > 0:
            target = highest_prev + 2.0
        else:
            target = 0.88 * DAILY_SALARY
    elif urgent:
        if dangerous_prev and low_supply:
            target = 0.86 * DAILY_SALARY
        elif highest_prev > 0:
            target = min(0.82 * DAILY_SALARY, highest_prev + 1.5)
        else:
            target = 0.72 * DAILY_SALARY
    else:
        if low_supply:
            if moderate_prev > 0:
                target = min(0.68 * DAILY_SALARY, moderate_prev + 1.5)
            elif dangerous_prev:
                target = 0.34 * DAILY_SALARY
            else:
                target = 0.52 * DAILY_SALARY
        elif mid_supply:
            if dangerous_prev:
                target = 0.26 * DAILY_SALARY
            elif moderate_prev > 0:
                target = min(0.58 * DAILY_SALARY, moderate_prev + 1.0)
            else:
                target = 0.42 * DAILY_SALARY
        else:
            if desperate_count >= 2:
                target = 0.38 * DAILY_SALARY
            else:
                target = 0.24 * DAILY_SALARY

    if day >= 8 and hp >= 6 and budget > 140 and low_supply:
        target = max(target, 0.62 * DAILY_SALARY)

    reserve_floor = 0.0
    if day <= 7:
        reserve_floor = 20.0
    max_affordable = max(0.0, budget - reserve_floor)
    if critical:
        max_affordable = budget

    bid = min(target, max_affordable)
    if bid <= 0 and budget > 0:
        bid = min(budget, 8.0 if not urgent else 20.0)

    if bid > budget:
        bid = budget
    if bid < 0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    if budget <= 0:
        return 0.0

    # Extract yesterday bids from immediate previous_trace only.
    prev_bids = []
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev.get('bid')))
            except Exception:
                pass

    # Baseline aggressiveness from supply pressure.
    # If supply is low, competition for the first WATER_REQ units is higher.
    if supply <= float(WATER_REQ):
        supply_pressure = 1.0
    elif supply <= (float(WATER_REQ) + 3.0):
        supply_pressure = 0.85
    elif supply <= 20.0:
        supply_pressure = 0.7
    else:
        supply_pressure = 0.55

    # React to yesterday's highest bid: high-bidder likely continues.
    if prev_bids:
        highest_prev_bid = max(prev_bids)
        avg_prev_bid = sum(prev_bids) / float(len(prev_bids))
    else:
        highest_prev_bid = 0.0
        avg_prev_bid = 0.0

    # If someone bid very low yesterday (like Eric), they likely won't outbid us.
    # If others bid high, we need to match a fraction of that to secure water.
    target = None

    # My urgency: each no-water day reduces survival; if already behind, bid harder.
    urgency = 0.0
    if no_water_days >= 1:
        urgency = 0.25
    if no_water_days >= 2:
        urgency = 0.5
    if hp <= 3:
        urgency = max(urgency, 0.6)

    # Decision bands.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        # Others were extremely aggressive; bid to avoid being starved.
        target = (0.55 + 0.25 * urgency) * highest_prev_bid
        # Also ensure we don't underbid relative to average.
        target = max(target, (0.65 + 0.15 * urgency) * avg_prev_bid)
    elif highest_prev_bid >= DAILY_SALARY * 0.6:
        target = (0.45 + 0.25 * urgency) * highest_prev_bid
        target = max(target, (0.55 + 0.15 * urgency) * avg_prev_bid)
    else:
        # No strong signal; bid moderately based on supply pressure.
        target = (0.4 + 0.35 * urgency) * DAILY_SALARY * supply_pressure

    # Convert target into a practical cap/floor.
    # We must not exceed budget; also avoid wasting too much early.
    # If supply is high, we can bid lower.
    if supply >= 22.0:
        waste_cap = 0.45 * DAILY_SALARY
    elif supply >= 18.0:
        waste_cap = 0.55 * DAILY_SALARY
    else:
        waste_cap = 0.7 * DAILY_SALARY

    bid = min(budget, min(target, waste_cap))

    # Ensure non-trivial bid when hp is low.
    if hp <= 2.0:
        bid = max(bid, min(budget, 0.85 * DAILY_SALARY))
    elif hp <= 4.0 and supply_pressure >= 0.7:
        bid = max(bid, min(budget, 0.65 * DAILY_SALARY))

    # Final clamp.
    if bid < 0.0:
        bid = 0.0

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    current_day = day_context['day']
    my_hp = my_status['hp']
    my_budget = my_status['budget']
    my_no_water_days = my_status['no_water_days']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_budget, DAILY_SALARY * 0.1)

    yesterday_bids = []
    for opp_id, opp_data in opponents_status.items():
        if opp_data['alive']:
            prev = opp_data.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                yesterday_bids.append(prev['bid'])

    highest_prev_bid = 0
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

    bid = DAILY_SALARY * 0.5 

    if my_hp <= 2 or my_no_water_days >= 1:
        bid = DAILY_SALARY * 1.2 
        if current_day >= EPISODE_DAYS - 2:
            bid = DAILY_SALARY * 1.5 
    elif my_hp <= 5:
        bid = DAILY_SALARY * 0.9 
    elif current_day >= EPISODE_DAYS - 3:
        bid = DAILY_SALARY * 1.1 

    if highest_prev_bid > 0:
        if bid <= highest_prev_bid:
            bid = highest_prev_bid + (DAILY_SALARY * 0.05) 
            if my_hp <= 3:
                bid = highest_prev_bid + (DAILY_SALARY * 0.1)

    bid = max(bid, DAILY_SALARY * 0.7)

    final_bid = min(my_budget, bid)

    return max(0.0, final_bid)

def get_bid(day_context, my_status, opponents_status):
